import{_ as a,o,c as l,a2 as r}from"./chunks/framework.DDEX3mHW.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1792059802000}'),t={name:"guide/faq.md"};function d(c,e,i,s,n,h){return o(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="面板与安装" tabindex="-1">面板与安装 <a class="header-anchor" href="#面板与安装" aria-label="Permalink to &quot;面板与安装&quot;">​</a></h2><h3 id="安装脚本提示-docker-command-not-found" tabindex="-1">安装脚本提示 &quot;Docker command not found&quot;？ <a class="header-anchor" href="#安装脚本提示-docker-command-not-found" aria-label="Permalink to &quot;安装脚本提示 &quot;Docker command not found&quot;？&quot;">​</a></h3><p>请确保您的系统已安装 Docker 和 Docker Compose。</p><ul><li>Ubuntu/Debian 安装 Docker: <code>curl -fsSL https://get.docker.com | bash</code></li></ul><h3 id="面板无法访问-connection-refused" tabindex="-1">面板无法访问 (Connection Refused)？ <a class="header-anchor" href="#面板无法访问-connection-refused" aria-label="Permalink to &quot;面板无法访问 (Connection Refused)？&quot;">​</a></h3><ol><li>检查防火墙是否放行了前端端口（默认 <code>6366</code>）。</li><li>检查容器是否正常运行: <code>docker ps</code>。</li><li>查看容器日志: <code>docker logs flux-panel-backend</code> 或 <code>docker logs vite-frontend</code>。</li></ol><h3 id="节点显示离线" tabindex="-1">节点显示离线？ <a class="header-anchor" href="#节点显示离线" aria-label="Permalink to &quot;节点显示离线？&quot;">​</a></h3><ol><li>检查节点服务器与面板服务器之间的网络连通性。</li><li>确认在节点端安装时输入的 <strong>面板地址</strong> 和 <strong>密钥</strong> 是否正确。</li><li>检查节点端服务状态: <code>systemctl status flux_agent</code>。</li><li>查看节点端日志: <code>journalctl -u flux_agent -f</code>。</li></ol><h3 id="只有-tcp-能通-udp-不通" tabindex="-1">只有 TCP 能通，UDP 不通？ <a class="header-anchor" href="#只有-tcp-能通-udp-不通" aria-label="Permalink to &quot;只有 TCP 能通，UDP 不通？&quot;">​</a></h3><p>请检查服务器防火墙和安全组（AWS/阿里云/腾讯云等）是否同时放行了对应端口的 <strong>TCP 和 UDP</strong> 协议。</p><h3 id="ipv6-无法使用" tabindex="-1">IPv6 无法使用？ <a class="header-anchor" href="#ipv6-无法使用" aria-label="Permalink to &quot;IPv6 无法使用？&quot;">​</a></h3><p>面板安装脚本会自动尝试配置 Docker 的 IPv6。如果失败，请手动检查 <code>/etc/docker/daemon.json</code> 配置，确保 <code>ipv6: true</code> 且分配了正确的 <code>fixed-cidr-v6</code> 子网。</p><h3 id="如何切换到-postgresql" tabindex="-1">如何切换到 PostgreSQL？ <a class="header-anchor" href="#如何切换到-postgresql" aria-label="Permalink to &quot;如何切换到 PostgreSQL？&quot;">​</a></h3><p>在 <code>.env</code> 文件中设置 <code>DB_TYPE=postgres</code>，并让 <code>DATABASE_URL</code> 与 <code>POSTGRES_*</code> 保持一致，然后执行 <code>docker compose up -d</code> 重启服务即可。使用安装脚本部署时，<code>POSTGRES_PASSWORD</code> 会自动随机生成并写入 <code>.env</code>。详见 <a href="./postgresql">PostgreSQL</a>。</p><h3 id="从-sqlite-迁移到-postgresql-后数据丢失" tabindex="-1">从 SQLite 迁移到 PostgreSQL 后数据丢失？ <a class="header-anchor" href="#从-sqlite-迁移到-postgresql-后数据丢失" aria-label="Permalink to &quot;从 SQLite 迁移到 PostgreSQL 后数据丢失？&quot;">​</a></h3><ol><li>确认迁移前已备份 SQLite 文件（<code>gost.db.bak</code>）。</li><li>确认 <code>pgloader</code> 命令执行成功，检查其输出是否有报错。</li><li>确认 <code>.env</code> 中 <code>DATABASE_URL</code> 的密码与 <code>POSTGRES_PASSWORD</code> 一致。</li><li>详细迁移步骤参考 <a href="./postgresql">PostgreSQL</a>。</li></ol><h3 id="postgresql-容器启动失败" tabindex="-1">PostgreSQL 容器启动失败？ <a class="header-anchor" href="#postgresql-容器启动失败" aria-label="Permalink to &quot;PostgreSQL 容器启动失败？&quot;">​</a></h3><ol><li>检查 <code>POSTGRES_PASSWORD</code> 是否已设置（不能为空）。</li><li>查看容器日志：<code>docker logs flux-panel-postgres</code>。</li><li>如果是首次启动后修改了密码，需要删除旧的数据卷重新初始化：<code>docker volume rm postgres_data</code>。</li></ol><h2 id="节点与订阅" tabindex="-1">节点与订阅 <a class="header-anchor" href="#节点与订阅" aria-label="Permalink to &quot;节点与订阅&quot;">​</a></h2><h3 id="内核状态显示-异常" tabindex="-1">内核状态显示“异常” <a class="header-anchor" href="#内核状态显示-异常" aria-label="Permalink to &quot;内核状态显示“异常”&quot;">​</a></h3><p>在“内核”标签里点击该内核 → “日志”查看原因，常见的有端口被占用、证书路径不存在、IPv6 被禁用（见 <a href="./nodes#监听地址">搭建节点 - 监听地址</a>）。</p><h3 id="流量一直是-0" tabindex="-1">流量一直是 0 <a class="header-anchor" href="#流量一直是-0" aria-label="Permalink to &quot;流量一直是 0&quot;">​</a></h3><p>检查节点是否安装了 nftables；流量每分钟左右同步一次。</p><h3 id="acme-一直申请不到证书" tabindex="-1">ACME 一直申请不到证书 <a class="header-anchor" href="#acme-一直申请不到证书" aria-label="Permalink to &quot;ACME 一直申请不到证书&quot;">​</a></h3><p>确认域名已解析到节点；HTTP 验证时 80 端口不能被其他程序占用，并且要能从公网访问；也可以改用 DNS 验证。</p><h3 id="snell-用哪个版本" tabindex="-1">Snell 用哪个版本 <a class="header-anchor" href="#snell-用哪个版本" aria-label="Permalink to &quot;Snell 用哪个版本&quot;">​</a></h3><p>入站的 Snell 版本不能高于节点安装的 Snell 主版本，v5 入站需要节点安装 Snell 5.x。</p><h3 id="reality-用-clash-mihomo-连不上" tabindex="-1">Reality 用 Clash / Mihomo 连不上 <a class="header-anchor" href="#reality-用-clash-mihomo-连不上" aria-label="Permalink to &quot;Reality 用 Clash / Mihomo 连不上&quot;">​</a></h3><p>Xray 26.7.11 起，Reality 未设置“最低客户端版本”时默认只接受 26.3.27 及以上的客户端，而 Mihomo（Clash Verge、Stash、FlClash 等）上报的版本是 1.8.2，会被拒绝。面板默认把最低客户端版本设为 <code>1.0.0</code>，所有客户端都能连接；如需调整，在 Reality 设置里修改“最低客户端版本”。也可以在安装内核时选择旧版本的 Xray。</p><h3 id="面板自升级提示-部署docker-compose-yml不可用" tabindex="-1">面板自升级提示“部署docker-compose.yml不可用” <a class="header-anchor" href="#面板自升级提示-部署docker-compose-yml不可用" aria-label="Permalink to &quot;面板自升级提示“部署docker-compose.yml不可用”&quot;">​</a></h3><p>见 <a href="./upgrade#修复面板内升级">升级</a>。</p><h3 id="用-ip-访问时复制失败" tabindex="-1">用 IP 访问时复制失败 <a class="header-anchor" href="#用-ip-访问时复制失败" aria-label="Permalink to &quot;用 IP 访问时复制失败&quot;">​</a></h3><p>浏览器只在 HTTPS 页面里完全开放复制功能。面板会自动改用兼容方式复制，仍失败时会提示；建议通过 HTTPS 域名访问面板，或长按文字手动复制。</p>',34)])])}const m=a(t,[["render",d]]);export{p as __pageData,m as default};
